package com.anamcara.controller;
import com.anamcara.model.SiteContent;import com.anamcara.repository.SiteContentRepository;import com.anamcara.service.S3MediaService;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.dynamodb.DynamoDbClient;import software.amazon.awssdk.services.dynamodb.model.*;import java.util.*;
@RestController @RequestMapping("/api/content")public class SiteContentDeleteController{private final SiteContentRepository repository;private final S3MediaService media;private final DynamoDbClient db;private final String table;public SiteContentDeleteController(SiteContentRepository repository,S3MediaService media,@Value("${aws.region}")String region,@Value("${app.dynamodb.table}")String table){this.repository=repository;this.media=media;this.db=DynamoDbClient.builder().region(Region.of(region)).build();this.table=table;}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable String id){SiteContent item=repository.findAll().stream().filter(c->id.equals(c.id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Content item not found."));Delete d=Delete.builder().tableName(table).key(Map.of("id",AttributeValue.builder().s(id).build())).conditionExpression("recordType=:type").expressionAttributeValues(Map.of(":type",AttributeValue.builder().s("SITE_CONTENT").build())).build();db.transactWriteItems(TransactWriteItemsRequest.builder().transactItems(TransactWriteItem.builder().delete(d).build()).build());if(item.mediaUrl.startsWith("/api/uploads/"))media.delete(item.mediaUrl.substring(13));else if(item.mediaUrl.startsWith("/uploads/"))media.delete(item.mediaUrl.substring(9));}}
